export const getCommunesByWilaya = (wilayaId: number): Commune[] => {
  return ALGERIAN_COMMUNES.filter(c => c.wilaya_id === wilayaId);
};

export const getCommuneById = (id: string): Commune | undefined => {
  return ALGERIAN_COMMUNES.find(c => c.id === id);
};

export const getCommuneName = (commune: Commune | undefined, lang: string = 'ar'): string => {
  if (!commune) return '';
  if (lang === 'fr') return commune.name_fr;
  if (lang === 'en') return commune.name_en;
  return commune.name_ar;
};
